const rows = $json.rows;
const todayISO = $('Set Date Context').first().json.todayISO;

const MILESTONES = [
  { days: 60, label: '2 months' },
  { days: 30, label: '1 month' },
  { days: 14, label: '2 weeks' },
  { days: 7,  label: '1 week' },
  { days: 1,  label: '1 day' },
];

const [todayY, todayM, todayD] = todayISO.split('-').map(Number);
const today = new Date(Date.UTC(todayY, todayM - 1, todayD));

const matchingInterns = [];

for (const row of rows) {
  if (!row.end_date) continue;
  const [endY, endM, endD] = row.end_date.split('-').map(Number);
  const endDate = new Date(Date.UTC(endY, endM - 1, endD));
  const diffMs = endDate.getTime() - today.getTime();
  const daysLeft = Math.round(diffMs / (1000 * 60 * 60 * 24));

  const milestone = MILESTONES.find(m => m.days === daysLeft);
  if (!milestone) continue;

  const emp = row.employee || {};
  const firstName = emp.first_name || '';
  const lastName = emp.last_name || '';
  const internName = `${firstName} ${lastName}`.trim() || 'Unknown Intern';

  matchingInterns.push({
    id: row.id,
    internName,
    endDate: row.end_date,
    department: row.department || 'Unassigned',
    school: row.school || null,
    program: row.program || null,
    daysLeft,
    milestoneLabel: milestone.label,
  });
}

return [{ json: { milestoneInterns: matchingInterns, count: matchingInterns.length } }];

const body = Array.isArray($json.body) ? $json.body : JSON.parse($json.body || '[]');

const ADMIN_ROLES = ['admin', 'super_admin'];

const adminTargets = body
  .filter(row => {
    const user = Array.isArray(row.users) ? row.users[0] : (row.users || {});
    const meta = row.metadata || {};
    return (
      ADMIN_ROLES.includes(user.role) &&
      user.deleted_at === null &&
      meta.telegram === true &&
      Boolean(meta.telegramChatId)
    );
  })
  .map(row => {
    const user = Array.isArray(row.users) ? row.users[0] : row.users;
    return {
      userId: row.user_id,
      fullName: user.full_name || 'Admin',
      chatId: String(row.metadata.telegramChatId),
    };
  });

return [{ json: { adminTargets } }];

const milestoneInterns = $('Compute Milestone Interns').first().json.milestoneInterns;
const adminTargets = $json.adminTargets;

if (!adminTargets || adminTargets.length === 0) return [];
if (!milestoneInterns || milestoneInterns.length === 0) return [];

const div = '━━━━━━━━━━━━━━━━━━';
const output = [];

for (const intern of milestoneInterns) {
  let urgencyEmoji = '📅';
  if (intern.daysLeft === 1) urgencyEmoji = '🚨';
  else if (intern.daysLeft <= 7) urgencyEmoji = '⚠️';
  else if (intern.daysLeft <= 14) urgencyEmoji = '🔔';

  const lines = [
    `${urgencyEmoji} <b>[DEV] Intern End Date Reminder</b>`,
    '',
    div,
    '',
    `👤 <b>Intern:</b> ${intern.internName}`,
    `🏢 <b>Department:</b> ${intern.department}`,
  ];

  if (intern.school) lines.push(`🎓 <b>School:</b> ${intern.school}`);
  if (intern.program) lines.push(`📚 <b>Program:</b> ${intern.program}`);

  lines.push('');
  lines.push(`📅 <b>End Date:</b> ${intern.endDate}`);
  lines.push(`⏳ <b>Days Remaining:</b> <b>${intern.daysLeft} day${intern.daysLeft === 1 ? '' : 's'}</b>`);
  lines.push(`🏁 <b>Milestone:</b> ${intern.milestoneLabel} left`);
  lines.push('');
  lines.push(div);
  lines.push('<i>Control Hub HR Portal — DEV/Staging</i>');

  const message = lines.join('\n');

  for (const admin of adminTargets) {
    output.push({
      json: {
        chatId: admin.chatId,
        message,
        internName: intern.internName,
        adminName: admin.fullName,
      }
    });
  }
}

return output;
